const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');
const sourcePath = path.join(root, 'src', 'index.js');
const outputPath = path.join(root, 'web', 'mako-edifact-sanitizer.browser.js');
const source = fs.readFileSync(sourcePath, 'utf8');

if (!source.includes("const crypto = require('node:crypto');")) {
  throw new Error('Expected src/index.js to import node:crypto');
}
if (!source.includes('module.exports = { sanitize,')) {
  throw new Error('Expected src/index.js CommonJS export shape');
}

const browserSource = source.replace(
  "const crypto = require('node:crypto');",
  'const crypto = makeBrowserCrypto();'
);

const header = `/* Generated by scripts/build-web-bundle.js from src/index.js. Do not edit by hand. */
(function (global) {
  'use strict';

  function makeBrowserCrypto() {
    function rightRotate(value, amount) {
      return (value >>> amount) | (value << (32 - amount));
    }

    function sha256(ascii) {
      var mathPow = Math.pow;
      var maxWord = mathPow(2, 32);
      var lengthProperty = 'length';
      var i;
      var j;
      var result = '';
      var words = [];
      var asciiBitLength = ascii[lengthProperty] * 8;
      var hash = sha256.h = sha256.h || [];
      var k = sha256.k = sha256.k || [];
      var primeCounter = k[lengthProperty];
      var isComposite = {};
      for (var candidate = 2; primeCounter < 64; candidate++) {
        if (!isComposite[candidate]) {
          for (i = 0; i < 313; i += candidate) isComposite[i] = candidate;
          hash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
          k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
        }
      }

      ascii += '\\x80';
      while ((ascii[lengthProperty] % 64) - 56) ascii += '\\x00';
      for (i = 0; i < ascii[lengthProperty]; i++) {
        j = ascii.charCodeAt(i);
        if (j >> 8) throw new Error('Browser SHA-256 shim only supports byte strings');
        words[i >> 2] |= j << (((3 - i) % 4) * 8);
      }
      words[words[lengthProperty]] = ((asciiBitLength / maxWord) | 0);
      words[words[lengthProperty]] = (asciiBitLength);

      for (j = 0; j < words[lengthProperty];) {
        var w = words.slice(j, j += 16);
        var oldHash = hash.slice(0);
        for (i = 0; i < 64; i++) {
          var w15 = w[i - 15];
          var w2 = w[i - 2];
          var a = hash[0];
          var e = hash[4];
          var temp1 = hash[7]
            + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))
            + ((e & hash[5]) ^ ((~e) & hash[6]))
            + k[i]
            + (w[i] = (i < 16) ? w[i] : (
              w[i - 16]
              + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))
              + w[i - 7]
              + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
            ) | 0);
          var temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22))
            + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
          hash = [(temp1 + temp2) | 0].concat(hash);
          hash[4] = (hash[4] + temp1) | 0;
        }
        for (i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
      }

      for (i = 0; i < 8; i++) {
        for (j = 3; j + 1; j--) {
          var b = (hash[i] >> (j * 8)) & 255;
          result += ((b < 16) ? 0 : '') + b.toString(16);
        }
      }
      return result;
    }

    return {
      createHash: function createHash(algorithm) {
        if (algorithm !== 'sha256') throw new Error('Unsupported browser hash algorithm: ' + algorithm);
        var chunks = '';
        return {
          update: function update(value) { chunks += String(value); return this; },
          digest: function digest(encoding) {
            if (encoding !== 'hex') throw new Error('Unsupported browser digest encoding: ' + encoding);
            return sha256(chunks);
          }
        };
      }
    };
  }

  var module = { exports: {} };
  var exports = module.exports;
  var process = { env: {} };

`;
const footer = `

  global.MakoEdifactSanitizer = module.exports;
})(typeof globalThis !== 'undefined' ? globalThis : window);
`;
const bundle = header + browserSource + footer;

fs.mkdirSync(path.dirname(outputPath), { recursive: true });
fs.writeFileSync(outputPath, bundle);
process.stdout.write(`built ${path.relative(root, outputPath)} from ${path.relative(root, sourcePath)}\n`);
